<template>
  <section class="page">
    <div class="page-heading"><div><h2>Mon temps de travail</h2><p class="muted">Pointage, planning et éléments de temps de la période.</p></div><button class="button" @click="loadAll">Actualiser</button></div>
    <div v-if="error" class="alert error">{{ error }}</div><div v-if="notice" class="alert success">{{ notice }}</div>
    <div class="card clock-card"><div><span class="muted">Aujourd’hui · {{ todayLabel }}</span><h2>{{ clock }}</h2><p>{{ openEntry ? `Entrée enregistrée à ${time(openEntry.dateHeure)}` : 'Aucune entrée ouverte' }}</p></div><button class="button primary" :disabled="busy || !employeeId" @click="punch">{{ busy ? 'Enregistrement…' : openEntry ? 'Pointer ma sortie' : 'Pointer mon entrée' }}</button></div>
    <div class="stat-cards"><article class="card stat-card"><span>Temps travaillé</span><strong>{{ duration(recap.minutes_travaillees ?? recap.minutesTravaillees) }}</strong></article><article class="card stat-card"><span>Retards</span><strong>{{ duration(recap.minutes_retard ?? recap.minutesRetard) }}</strong></article><article class="card stat-card"><span>Heures supplémentaires</span><strong>{{ duration(recap.minutes_sup ?? recap.minutesSupplementaires) }}</strong></article><article class="card stat-card"><span>Absences à qualifier</span><strong>{{ duration(recap.minutes_absence ?? recap.minutesAbsenceNonJustifiee) }}</strong></article></div>
    <div class="card toolbar"><label>Mois du récapitulatif <input type="month" v-model="month" @change="loadRecap"></label><label>Période affichée <select v-model="range" @change="loadRecords"><option value="week">Cette semaine</option><option value="month">Ce mois</option></select></label></div>
    <div class="detail-grid"><article class="card"><h3>Mon planning</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Horaire</th><th>Type</th><th>Source</th></tr></thead><tbody><tr v-for="item in planning" :key="item.id"><td>{{ date(item.date) }}</td><td>{{ item.heureDebut }} – {{ item.heureFin }}</td><td>{{ item.type }}</td><td>{{ item.source }}</td></tr><tr v-if="!planning.length"><td colspan="4" class="empty">Aucun horaire sur cette période.</td></tr></tbody></table></div></article>
      <article class="card"><h3>Historique de pointage</h3><div class="table-wrap"><table><thead><tr><th>Date et heure</th><th>Sens</th><th>Source</th></tr></thead><tbody><tr v-for="item in pointages" :key="item.id"><td>{{ dateTime(item.dateHeure) }}</td><td>{{ item.sens }}</td><td>{{ item.source }}</td></tr><tr v-if="!pointages.length"><td colspan="3" class="empty">Aucun pointage sur cette période.</td></tr></tbody></table></div></article></div>
    <div class="detail-grid"><article class="card"><h3>Mes demandes d’heures supplémentaires</h3><form class="inline-form" @submit.prevent="requestOvertime"><label>Date <input type="date" v-model="overtime.date" required></label><label>Durée (minutes) <input type="number" v-model.number="overtime.minutes" min="1" required></label><label>Motif <input v-model="overtime.motif" required maxlength="1000"></label><button class="button primary" :disabled="busy">Envoyer</button></form><div class="table-wrap"><table><thead><tr><th>Date</th><th>Durée</th><th>Statut</th><th>Motif</th></tr></thead><tbody><tr v-for="item in overtimeRequests" :key="item.id"><td>{{ date(item.date) }}</td><td>{{ duration(item.minutes) }}</td><td>{{ item.statut }}</td><td>{{ item.motif }}</td></tr><tr v-if="!overtimeRequests.length"><td colspan="4" class="empty">Aucune demande.</td></tr></tbody></table></div></article>
      <article class="card"><h3>Mes anomalies</h3><div v-for="item in anomalies" :key="item.id" class="notification-item"><strong>{{ date(item.date) }} · {{ item.type }}</strong><span>{{ item.commentaire || 'Une anomalie nécessite votre attention.' }}</span><form class="inline-form" @submit.prevent="justify(item)"><input v-model="item.justification" placeholder="Votre justification" required><button class="button">Justifier</button></form></div><p v-if="!anomalies.length" class="empty">Aucune anomalie ouverte.</p></article></div>
  </section>
</template>
<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import api from '@/api/axios'
import { formatApiError } from '@/utils/errors'
const employeeId=ref(null), error=ref(''), notice=ref(''), busy=ref(false), clock=ref(''), range=ref('week'), month=ref(new Date().toISOString().slice(0,7))
const pointages=ref([]), planning=ref([]), recap=ref({}), overtimeRequests=ref([]), anomalies=ref([])
const overtime=ref({date:new Date().toISOString().slice(0,10),minutes:60,motif:''})
const todayLabel=new Intl.DateTimeFormat('fr-FR',{dateStyle:'full',timeZone:'Indian/Antananarivo'}).format(new Date())
const openEntry=computed(()=>{const rows=[...pointages.value].sort((a,b)=>new Date(b.dateHeure)-new Date(a.dateHeure));return rows[0]?.sens==='ENTREE'?rows[0]:null})
let timer
function tick(){clock.value=new Intl.DateTimeFormat('fr-FR',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Indian/Antananarivo'}).format(new Date())}
function duration(value=0){const n=Number(value)||0;return `${Math.floor(n/60)} h ${String(n%60).padStart(2,'0')}`}
function date(value){return value?new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeZone:'Indian/Antananarivo'}).format(new Date(`${value}T12:00:00`)):'—'}
function time(value){return new Intl.DateTimeFormat('fr-FR',{hour:'2-digit',minute:'2-digit',timeZone:'Indian/Antananarivo'}).format(new Date(value))}
function dateTime(value){return new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short',timeZone:'Indian/Antananarivo'}).format(new Date(value))}
function bounds(){const now=new Date(), start=new Date(now);if(range.value==='week'){const day=(start.getDay()+6)%7;start.setDate(start.getDate()-day)}else start.setDate(1);const end=new Date(start);if(range.value==='week')end.setDate(start.getDate()+6);else end.setMonth(start.getMonth()+1,0);return [start.toISOString().slice(0,10),end.toISOString().slice(0,10)]}
async function loadAll(){error.value='';try{if(!employeeId.value){const employees=(await api.get('/employes')).data;employeeId.value=employees?.[0]?.id}if(!employeeId.value)return;await Promise.all([loadRecords(),loadRecap(),loadRequests(),loadAnomalies()])}catch(e){error.value=formatApiError(e)}}
async function loadRecords(){if(!employeeId.value)return;const [du,au]=bounds();try{const [p,t]=await Promise.all([api.get(`/employes/${employeeId.value}/planning`,{params:{du,au}}),api.get(`/employes/${employeeId.value}/pointages`,{params:{du,au}})]);planning.value=p.data;pointages.value=t.data}catch(e){error.value=formatApiError(e)}}
async function loadRecap(){if(!employeeId.value)return;try{recap.value=(await api.get(`/employes/${employeeId.value}/temps/recap`,{params:{mois:month.value}})).data}catch(e){error.value=formatApiError(e)}}
async function loadRequests(){try{overtimeRequests.value=(await api.get('/heures-sup')).data}catch(e){error.value=formatApiError(e)}}
async function loadAnomalies(){try{anomalies.value=(await api.get('/anomalies',{params:{statut:'OUVERTE'}})).data}catch(e){error.value=formatApiError(e)}}
async function punch(){busy.value=true;error.value='';notice.value='';try{const result=(await api.post('/pointages',{sens:openEntry.value?'SORTIE':'ENTREE'})).data;if(result.accepte===false)throw new Error(result.message||result.erreur||'Pointage refusé.');notice.value='Pointage enregistré.';await loadAll()}catch(e){error.value=e.response?formatApiError(e):e.message}finally{busy.value=false}}
async function requestOvertime(){busy.value=true;try{await api.post('/heures-sup',overtime.value);notice.value='Demande d’heures supplémentaires transmise.';overtime.value.motif='';await loadRequests()}catch(e){error.value=formatApiError(e)}finally{busy.value=false}}
async function justify(item){try{await api.post(`/anomalies/${item.id}/justifier`,{commentaire:item.justification});notice.value='Justification transmise.';await loadAnomalies()}catch(e){error.value=formatApiError(e)}}
onMounted(()=>{tick();timer=setInterval(tick,1000);loadAll()});onUnmounted(()=>clearInterval(timer))
</script>
